// DecodeRegisteredEvent decodes a "Registered(address,uint256,uint256,uint8)" log.
func (c *IDiesisConductorsBinding) DecodeRegisteredEvent(log types.Log) (out IDiesisConductorsRegisteredEvent, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI event: %v", failure)
		}
	}()
	definition, err := c.event("Registered(address,uint256,uint256,uint8)")
	if err != nil {
		return out, err
	}
	if len(log.Topics) == 0 || log.Topics[0] != definition.ID {
		return out, fmt.Errorf("event signature mismatch for %s", "Registered(address,uint256,uint256,uint8)")
	}
	if len(log.Topics) != 2 {
		return out, fmt.Errorf("event topic count mismatch for %s", "Registered(address,uint256,uint256,uint8)")
	}
	if len(definition.Inputs.NonIndexed()) > 0 {
		values, err := definition.Inputs.NonIndexed().Unpack(log.Data)
		if err != nil {
			return out, err
		}
		if len(values) != 3 {
			return out, fmt.Errorf("event value count mismatch")
		}
		out.Added = *abi.ConvertType(values[0], new(*big.Int)).(**big.Int)
		out.NewBond = *abi.ConvertType(values[1], new(*big.Int)).(**big.Int)
		out.NewTier = *abi.ConvertType(values[2], new(uint8)).(*uint8)
	} else if len(log.Data) != 0 {
		return out, fmt.Errorf("unexpected event data")
	}
	var indexed abi.Arguments
	var indexedTopics []common.Hash
	indexed = append(indexed, definition.Inputs[0])
	indexedTopics = append(indexedTopics, log.Topics[1])
	if err := abi.ParseTopics(&out, indexed, indexedTopics); err != nil {
		return out, err
	}
	return out, nil
}

